import React, { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";

const loginSchema = z.object({
  username: z.string().min(1, "Username is required").max(50),
  password: z.string().min(1, "Password is required").max(100),
});

const DEMO_USERS = {
  admin:     { role: "scrb_analyst" },
  sp_blr:    { role: "sp" },
  insp_wf:   { role: "inspector" },
  constable: { role: "constable" }
};

export default function LoginPanel({ onLogin, users = DEMO_USERS }) {
  const [serverError, setServerError] = useState("");
  const [loading, setLoading] = useState(false);

  const { register, handleSubmit, formState: { errors }, setValue, clearErrors } = useForm({
    resolver: zodResolver(loginSchema),
    defaultValues: { username: "", password: "" }
  });

  const onSubmit = async (data) => {
    setLoading(true);
    setServerError("");
    const res = await onLogin(data.username, data.password);
    setLoading(false);
    if (!res.success) {
      setServerError(res.error || "Invalid credentials");
    }
  };

  return (
    <div className="ref-login-wrapper">
      <div className="ref-login-container">
        
        {/* Left Panel */}
        <div className="ref-login-left">
          <div className="ref-brand-header">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <circle cx="12" cy="12" r="10" stroke="white" strokeWidth="2" strokeDasharray="4 2"/>
              <circle cx="12" cy="12" r="4" fill="white"/>
            </svg>
            <span>KSP INTELLIGENCE</span>
          </div>
          
          <div className="ref-left-content">
            <p className="ref-welcome-sub">Nice to see you again</p>
            <h1 className="ref-welcome-main">WELCOME BACK</h1>
            <div className="ref-divider"></div>
            <p className="ref-welcome-text">
              Securely access the Karnataka State Police Crime Intelligence Database.
              Ensure your connection is secure before authenticating your credentials.
            </p>
          </div>
          
          {/* Decorative Elements */}
          <div className="ref-deco ref-circle-1"></div>
          <div className="ref-deco ref-circle-2"></div>
          <svg className="ref-deco-lines" viewBox="0 0 100 100" preserveAspectRatio="none">
            <line x1="0" y1="100" x2="100" y2="0" stroke="rgba(255,255,255,0.2)" strokeWidth="1"/>
            <line x1="20" y1="100" x2="100" y2="20" stroke="rgba(255,255,255,0.1)" strokeWidth="1"/>
          </svg>
          <div className="ref-wave-top"></div>
          <div className="ref-wave-bottom"></div>
        </div>

        {/* Right Panel */}
        <div className="ref-login-right">
          <div className="ref-right-content">
            <h2 className="ref-login-title">Login Account</h2>
            <p className="ref-login-subtitle">
              Enter your official email ID and password to access the restricted SCRB portal. All activities are monitored.
            </p>
            
            <form onSubmit={handleSubmit(onSubmit)} className="ref-form">
              <div className="ref-input-wrapper">
                <input 
                  type="text" 
                  placeholder="Officer Username / Email ID" 
                  {...register("username")} 
                  className="ref-input"
                  disabled={loading}
                />
              </div>
              {errors.username && <p className="ref-error">{errors.username.message}</p>}
              
              <div className="ref-input-wrapper">
                <input 
                  type="password" 
                  placeholder="Password" 
                  {...register("password")} 
                  className="ref-input"
                  disabled={loading}
                />
              </div>
              {errors.password && <p className="ref-error">{errors.password.message}</p>}
              
              {serverError && <p className="ref-error ref-server-error">{serverError}</p>}
              
              <div className="ref-form-options">
                <label className="ref-checkbox">
                  <input type="checkbox" />
                  <span className="checkmark"></span>
                  Keep me signed in
                </label>
                <a href="#" className="ref-link">Forgot password?</a>
              </div>
              
              <button type="submit" className="ref-submit-btn" disabled={loading}>
                {loading ? "AUTHENTICATING..." : "LOGIN"}
              </button>
            </form>

            <div className="ref-demo-section">
               <p className="ref-demo-label">Demo Access (One-Click):</p>
               <div className="ref-demo-grid">
                  {Object.entries(users).map(([u,d])=>(
                    <button key={u} type="button" className="ref-demo-btn" onClick={()=>{
                      setValue("username", u);
                      setValue("password", u);
                      clearErrors();
                      setServerError("");
                    }} disabled={loading}>
                       {u} ({d.role.replace("_", " ")})
                    </button>
                  ))}
               </div>
            </div>

          </div>
        </div>
        
      </div>
    </div>
  );
}
